    belakang += '<rect class="zn zn-' + kls + '" x="' + PADL + '" y="' + f(Math.min(yt, yb))
      + '" width="' + f(kanan - PADL) + '" height="' + f(Math.max(2, Math.abs(yb - yt))) + '">'
      + '<title>' + esc(z.nama) + ' ' + rb(lo) + (hi > lo ? '–' + rb(hi) : '')
